const {esc,icon,brand,card,query}=Norm;
const isAI=document.body.dataset.scenario==='ai';
const statuses=isAI?{done:['Завершён','green'],running:['В работе','blue'],error:['Ошибка','red'],queued:['В очереди','gray']}:{investigation:['Расследование','blue'],review:['Расследование РМ','violet'],rework:['Доработка','blue'],approval:['Утверждение','violet']};
const title=isAI?'Запуски AI-анализа документов':'Это все события';
const desc='Описание: 24 мая 2024 г. в 15:30 сотрудник отдела маркетинга Специалист 03 загрузила файл с конфиденциальными данными клиентов в публичное облачное хранилище. В 16:15 система DLP заблокировала попытку передачи данных.';
const items=isAI?[
 ['AI-1087','Договор поставки оборудования № 42','done','2026-10-08','09:42','12 рисков','Сопоставлены условия договора и политика закупок. Найдены риски сроков поставки и ответственности.','Специалист 02',true],
 ['AI-1086','Отчёт внутреннего аудита — III квартал','running','2026-10-08','09:18','Анализируется','Проверка замечаний аудита и связанных мер. Обработано 18 из 24 страниц.','Норма AI',false],
 ['AI-1085','Регламент информационной безопасности','error','2026-10-07','17:24','Требуется повтор','Не удалось прочитать страницы 7–9: файл защищён паролем. История запуска сохранена.','Специалист 02',true],
 ['AI-1084','Политика управления операционными рисками','done','2026-10-06','12:05','3 риска','Проверены правила эскалации, контрольные процедуры и назначение ответственных.','Норма AI',false],
 ['AI-1083','Изменения в договоре аренды','queued','2026-10-03','14:32','Ожидает запуска','Документ принят. Запуск ожидает свободного обработчика.','Специалист 02',true],
 ['AI-1082','Акт проверки подразделения','done','2026-09-28','11:46','7 рисков','Выявлены недостатки контрольных процедур. Результаты доступны для проверки.','Норма AI',false]
].map(([id,t,status,date,time,result,description,owner,mine])=>({id,title:t,status,date,dateLabel:date.split('-').reverse().join('.'),color:statuses[status][1],statusLabel:statuses[status][0],elapsed:time,metrics:[['Результат',result],['Документ','PDF · 24 стр.']],description,owner,mine,org:'ООО «Тестовая компания»'})):
 ['review','investigation','rework','approval','approval','investigation'].map((status,i)=>({id:'EVE-'+(173+i),title:'Утечка или компрометация персональных данных клиентов',status,color:statuses[status][1],statusLabel:statuses[status][0],date:'2025-12-19',dateLabel:'19.12.2025',elapsed:i===3?'64 дня в работе':'4 дня в работе',metrics:[['Прямые',i?'2 300 000 ₽':'0 ₽'],['Косвенные',i===1?'1 600 000 ₽':i?'2 300 000 ₽':'0 ₽']],description:desc,owner:i?'Норма AI':'Специалист 02',mine:i<2,org:'ООО «Тестовая компания»'}));
const state={scope:'all',quick:[],search:'',applied:{status:'',from:'',to:''},demo:'default'};
document.querySelector('.brand').innerHTML=brand()+'НОРМ';document.querySelector('h1').textContent=title;document.title='НОРМ — '+title;
document.querySelector('[data-icon-search]').innerHTML=icon('search');document.querySelector('[data-icon-filter]').innerHTML=icon('filter')+'<span>Фильтр</span>';document.querySelector('.search-row>span').innerHTML=icon('search');document.querySelector('.assistant').innerHTML=brand('ai');
document.querySelector('[data-main-action]').textContent=isAI?'Запустить анализ':'Зарегистрировать событие';
document.querySelector('.segment-option').textContent=isAI?'Все запуски':'Все события';document.querySelector('[data-scope="mine"]').textContent=isAI?'Мои запуски':'Мои в работе';
document.querySelector('[data-nav-active]').textContent=isAI?'AI мониторинг':'События';
document.querySelector('.quick-filters').innerHTML=isAI?'<span class="filter-divider">/</span>'+['running','error'].map(s=>`<button class="filter-chip" data-quick="${s}" aria-pressed="false">${statuses[s][0]}<b>${items.filter(x=>x.status===s).length}</b></button>`).join(''):'';
document.querySelector('.overview').hidden=!isAI;
function render(){
 const focusedId=document.activeElement?.closest('.entity-card')?.dataset.id;
 const visible=query(items,state);document.querySelector('.registry').innerHTML=visible.map(card).join('');
 if(focusedId){(document.querySelector(`[data-id="${CSS.escape(focusedId)}"]`)||document.querySelector('[data-main-action]')).focus();}
 document.querySelectorAll('[data-demo]').forEach(b=>{const active=b.dataset.demo===state.demo;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
 const has=Boolean(state.search||state.quick.length||state.applied.status||state.applied.from||state.applied.to||state.scope==='mine');
 document.querySelector('.result-context').textContent=has?`Найдено ${visible.length} из ${items.length}${state.applied.from?' · от '+state.applied.from:''}${state.applied.to?' · до '+state.applied.to:''}`:'';
 document.querySelector('[data-icon-filter]').classList.toggle('has-filters',Boolean(state.applied.status||state.applied.from||state.applied.to));
 document.querySelectorAll('[data-state]').forEach(e=>e.hidden=true);
 document.querySelector(`[data-state="${state.demo==='default'&&!visible.length?'empty':state.demo}"]`).hidden=false;
 document.querySelector('[data-reset]').textContent=state.demo==='empty'?'Вернуть записи':has?'Сбросить фильтры':'Обновить список';
 document.querySelector('[data-empty-text]').textContent=has?'Измените условия поиска или сбросьте фильтры.':'В реестре пока нет записей.';
 document.querySelectorAll('[data-quick]').forEach(b=>{b.querySelector('b').textContent=items.filter(x=>x.status===b.dataset.quick).length;const active=state.quick.includes(b.dataset.quick);b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});
 document.querySelectorAll('.entity-card').forEach(b=>b.addEventListener('click',()=>details(items.find(x=>x.id===b.dataset.id),b)));
 document.querySelector('[data-icon-filter]').setAttribute('aria-label','Фильтр'+(state.applied.status||state.applied.from||state.applied.to?' — есть применённые условия':''));
 if(isAI){document.querySelector('[data-overview-total]').textContent=items.length;document.querySelector('[data-overview-done]').textContent=items.filter(x=>x.status==='done').length;document.querySelector('[data-overview-error]').textContent=items.filter(x=>x.status==='error').length;document.querySelector('.bar span').style.width=items.filter(x=>x.status==='done').length/items.length*100+'%';}
}
function details(d,trigger){
 const el=Norm.open(`<header class="modal-header"><div><p class="eyebrow">${isAI?'AI-анализ документов':'Событие'} · <span class="status status-${d.color}">${esc(d.statusLabel)}</span></p><h2>${esc(d.title)}</h2></div><button class="icon-button" data-close-surface aria-label="Закрыть текущее окно">×</button></header><div class="object-workspace"><div class="modal-body"><section class="modal-section"><h3>${isAI?'Результат анализа':'Описание события'}</h3><p>${esc(d.description)}</p>${isAI?'<p class="quiet">Выводы сформированы AI и требуют проверки ответственным сотрудником.</p>':''}</section><section class="modal-section"><h3>${isAI?'Документ и ход обработки':'Обстоятельства'}</h3><p>${isAI?'Файл: '+esc(d.title)+'.pdf. '+(d.status==='done'?'Проверка завершена.':d.status==='running'?'Обработка продолжается.':d.status==='error'?'Обработка прервана. Причина указана выше.':'Документ ожидает обработки; результатов пока нет.'):'Событие зарегистрировано, назначен ответственный. Результаты расследования доступны в истории.'}</p><button class="button button-secondary" data-related>${isAI?'Открыть документ':'Связанный риск'} ${icon('arrow')}</button></section></div><aside class="action-meta-zone"><section class="rail-block"><h3>Информация</h3><dl class="meta-list"><div><dt>ID</dt><dd>${esc(d.id)}</dd></div><div><dt>Дата</dt><dd>${esc(d.dateLabel)}</dd></div><div><dt>Автор</dt><dd>${esc(d.owner)}</dd></div><div><dt>Статус</dt><dd>${esc(d.statusLabel)}</dd></div></dl></section><button class="rail-link" data-history>История изменений ${icon('arrow')}</button>${isAI?'<section class="rail-actions"><button class="button button-primary" data-retry>Повторить анализ</button></section>':''}</aside></div>`,trigger);
 el.querySelector('[data-related]').onclick=()=>Norm.open(`<header class="modal-header"><div><p class="eyebrow">Связанный объект</p><h2>${isAI?'Документ: '+esc(d.title):'Риск информационной безопасности'}</h2></div><button class="icon-button" data-close-surface aria-label="Назад к объекту">×</button></header><div class="modal-body"><p>${isAI?'Представительный просмотр исходного документа.':'Описание связанного риска и ссылка на событие '+esc(d.id)+'.'}</p><p>После закрытия сохраняются исходное окно, поиск и фильтры реестра.</p></div>`);
 el.querySelector('[data-history]').onclick=()=>Norm.drawer(`<header class="modal-header"><h2>История ${esc(d.id)}</h2><button class="icon-button" data-close-surface aria-label="Закрыть историю">×</button></header><div class="modal-body"><p>${esc(d.dateLabel)} — запись создана.</p><p>Текущий статус: ${esc(d.statusLabel)}.</p></div>`);
 if(isAI)el.querySelector('[data-retry]').onclick=()=>{addRun(d);Norm.close();};
}
function addRun(parent){const id='AI-'+(1088+items.filter(x=>x.parent).length);items.unshift({...parent,id,status:'queued',statusLabel:statuses.queued[0],color:'gray',date:'2026-10-08',dateLabel:'08.10.2026',elapsed:'10:00',metrics:[['Результат','Ожидает запуска'],['Документ','PDF · 24 стр.']],description:`Новый запуск по документу. Исходный запуск ${parent.id} сохранён.`,parent:parent.id,mine:true});render();toast(`Создан ${id}; исходная запись сохранена`);}
function toast(t){document.querySelector('.toast')?.remove();const e=document.createElement('div');e.className='toast';e.setAttribute('role','status');e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),3500);}
document.querySelectorAll('[data-scope]').forEach(b=>b.onclick=()=>{state.scope=b.dataset.scope;document.querySelectorAll('[data-scope]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});render();});
document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>{state.quick=state.quick.includes(b.dataset.quick)?state.quick.filter(x=>x!==b.dataset.quick):[...state.quick,b.dataset.quick];render();});
document.querySelector('[data-icon-search]').onclick=()=>{const row=document.querySelector('.search-row');if(state.search){row.hidden=false;row.querySelector('input').focus();return;}row.hidden=!row.hidden;document.querySelector('[data-icon-search]').setAttribute('aria-expanded',String(!row.hidden));if(!row.hidden)row.querySelector('input').focus();};
document.querySelector('input[type="search"]').oninput=e=>{state.search=e.target.value;render();};
document.querySelector('[data-reset]').onclick=()=>{state.demo='default';state.search='';state.quick=[];state.scope='all';state.applied={status:'',from:'',to:''};document.querySelector('input[type="search"]').value='';document.querySelector('[data-scope="all"]').click();render();};
document.querySelector('[data-icon-filter]').onclick=()=>{
 const wrap=Norm.drawer(`<header class="drawer-header"><h2>Фильтр</h2><button class="icon-button" data-cancel aria-label="Закрыть фильтр">×</button></header><form class="drawer-content" id="filter-form"><fieldset><legend>Статус</legend><label class="field"><span>Статус ${isAI?'запуска':'события'}</span><select name="status"><option value="">Все статусы</option>${Object.entries(statuses).map(([v,[l]])=>`<option value="${v}">${l}</option>`).join('')}</select></label></fieldset><fieldset><legend>${isAI?'Период запуска':'Дата регистрации'}</legend><div class="date-range"><input type="date" name="from" aria-label="Дата от"><input type="date" name="to" aria-label="Дата до"></div></fieldset><p class="form-error" hidden role="alert">Дата начала должна быть не позже даты окончания.</p></form><footer class="drawer-footer"><button class="button button-secondary" data-reset-draft>Сбросить</button><button class="button button-primary" type="submit" form="filter-form">Применить</button></footer>`);const form=wrap.querySelector('form');Object.entries(state.applied).forEach(([k,v])=>form.elements[k].value=v);
 wrap.querySelector('[data-cancel]').onclick=()=>Norm.close();wrap.querySelector('[data-reset-draft]').onclick=()=>{form.reset();form.querySelector('.form-error').hidden=true;};form.onsubmit=e=>{e.preventDefault();const draft=Object.fromEntries(new FormData(form));if(draft.from&&draft.to&&draft.from>draft.to){form.querySelector('.form-error').hidden=false;return;}state.applied=draft;Norm.close();render();};
};
document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>{state.demo=b.dataset.demo;render();});document.querySelector('[data-recover]').onclick=()=>{state.demo='default';render();};
document.querySelector('[data-main-action]').onclick=()=>{if(isAI){const e=Norm.open(`<header class="modal-header"><h2>Запуск AI-анализа</h2><button class="icon-button" data-close-surface aria-label="Закрыть форму">×</button></header><div class="modal-body"><form id="launch-analysis" class="form-grid"><label class="form-wide">Документ<select name="document">${items.filter(x=>!x.parent).map(d=>`<option value="${esc(d.id)}">${esc(d.title)}</option>`).join('')}</select></label><p class="form-wide quiet">Демонстрационный запуск по выбранному документу. Результат появится новой записью в истории.</p></form></div><footer class="modal-footer"><button class="button button-secondary" data-close-surface>Отмена</button><button class="button button-primary" form="launch-analysis">Запустить</button></footer>`,document.activeElement,{type:'form'});e.querySelector('form').onsubmit=x=>{x.preventDefault();addRun(items.find(d=>d.id===new FormData(x.target).get('document')));Norm.close();};return;}const e=Norm.open('<header class="modal-header"><h2>Регистрация события</h2><button class="icon-button" data-close-surface aria-label="Закрыть форму">×</button></header><div class="modal-body"><form id="create-event" class="form-grid"><label class="form-wide">Описание события<input required name="title" placeholder="Краткое название события"></label></form></div><footer class="modal-footer"><button class="button button-secondary" data-close-surface>Отмена</button><button class="button button-primary" form="create-event">Зарегистрировать</button></footer>',document.activeElement,{type:'form'});e.querySelector('form').onsubmit=x=>{x.preventDefault();items.unshift({...items[0],id:'EVE-'+(173+items.length),title:new FormData(x.target).get('title'),mine:true});Norm.close();render();};};
document.querySelector('.assistant').onclick=()=>Norm.drawer('<header class="modal-header"><h2>Помощь Норма AI</h2><button class="icon-button" data-close-surface aria-label="Закрыть помощь">×</button></header><div class="modal-body"><p>Выберите запись, чтобы проверить её результат, историю или исходный документ. Используйте поиск и фильтр для уточнения списка.</p></div>');
document.querySelector('[data-overview-filter]')?.addEventListener('click',()=>{state.quick=['error'];render();});
if(new URLSearchParams(location.search).has('demo'))document.querySelector('.prototype-tools').classList.add('show');
render();

document.querySelectorAll('.app-nav nav a').forEach(a=>{a.innerHTML=icon('people')+a.querySelector('span').outerHTML;});document.querySelectorAll('[data-nav-passive]').forEach(a=>{a.removeAttribute('href');a.style.cursor='default';a.setAttribute('aria-disabled','true');});
